class MyCircularQueue {
    private static final class Node {
        int value;
        Node next;

        Node(int value) {
            this.value = value;
        }
    }

    private final int capacity;
    private Node head;
    private Node tail;
    private int size;

    public MyCircularQueue(int k) {
        capacity = k;
    }

    public boolean enQueue(int value) {
        if (isFull()) {
            return false;
        }
        Node node = new Node(value);
        if (isEmpty()) {
            head = node;
            tail = node;
        } else {
            tail.next = node;
            tail = node;
        }
        size++;
        return true;
    }

    public boolean deQueue() {
        if (isEmpty()) {
            return false;
        }
        head = head.next;
        size--;
        if (size == 0) {
            tail = null;
        }
        return true;
    }

    public int Front() {
        return isEmpty() ? -1 : head.value;
    }

    public int Rear() {
        return isEmpty() ? -1 : tail.value;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public boolean isFull() {
        return size == capacity;
    }
}

class MyCircularQueue {
    private static final class Node {
        int value;
        Node next;
    }

    private final int capacity;
    private Node read;
    private Node write;
    private Node lastWritten;
    private int size;

    public MyCircularQueue(int k) {
        capacity = k;
        Node first = new Node();
        Node previous = first;
        for (int i = 1; i < k; i++) {
            previous.next = new Node();
            previous = previous.next;
        }
        previous.next = first;
        read = first;
        write = first;
    }

    public boolean enQueue(int value) {
        if (isFull()) {
            return false;
        }
        write.value = value;
        lastWritten = write;
        write = write.next;
        size++;
        return true;
    }

    public boolean deQueue() {
        if (isEmpty()) {
            return false;
        }
        read = read.next;
        size--;
        return true;
    }

    public int Front() {
        return isEmpty() ? -1 : read.value;
    }

    public int Rear() {
        return isEmpty() ? -1 : lastWritten.value;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public boolean isFull() {
        return size == capacity;
    }
}
